        body: `【1】しくみ
ウイルスは二分裂しない。1個のウイルスが細胞に入ると、しばらくして何百・何千という子ウイルスが一度に出てくる。その仕組みは、①吸着・侵入・脱殻、②素材の合成（ゲノムの複製とタンパク合成）、③組み立て（成熟）、④放出、の4段階で説明できる。一気に増える秘密は②にある。親ウイルスのゲノムから直接子ウイルスの部品を作るのではなく、まず複製の酵素を作ってゲノムを大量に複製し、増えたゲノムそれぞれから構造蛋白を大量に作る。つまりゲノムの複製と蛋白質の合成を別々に大量生産し、最後にまとめて組み立てる。このため、脱殻してから組み立てが終わるまでの間は、細胞の中に感染性のある完成した粒子が1つもない時期ができる。これを暗黒期（eclipse）という。日食で月の影に隠れて太陽が見えないのと同じで、ウイルスは確かに細胞内にいるが、粒子としては見えない。

【2】覚えること
・増殖は==吸着・侵入・脱殻 → 素材の合成 → 組み立て（成熟） → 放出==
・「素材合成」と言われたら==ゲノムの複製とタンパク合成==を指す
・一気に増える秘密は==ゲノム複製と構造蛋白合成を別々に大量に行う==こと
・脱殻から組み立てまでの粒子がない時期が==暗黒期（eclipse）==

【3】試験ではこう出る
暗黒期の語や増殖曲線を直接問う設問は5年分で見られない。ただし記述問題（R4記述2・R3記述3）は「==素材合成（ゲノム複製とウイルス蛋白質の合成）を説明しなさい==」と問うので、素材合成という語が何を指すかは必ず押さえる。`,
