        body: `【1】しくみ
インフルエンザウイルスは、HA蛋白（リガンド）で細胞表面のシアル酸（レセプター）に吸着したあと、すぐには融合しない。まずエンドサイトーシスで細胞内に取り込まれ、エンドソームに入る。エンドソームの中は次第に酸性になる（pHの低下）。このpH低下が引き金になってHA蛋白の構造が変わり、融合ペプチドが露出してエンドソーム膜に刺さり、エンベロープ膜とエンドソーム膜の膜融合が進む。こうして脱殻が起こり、ゲノムRNA（8本の分節）が細胞質に放出され、核へ運ばれる。酸性の環境を待って融合するので、「エンドソームに入る」「pHが下がる」「膜融合する」の3つがすべてそろう。HIVが中性の形質膜で融合したのとの違いがこの論点の芯である。なお、HAがあらかじめHA1とHA2に開裂していないと融合できないこと、M2イオンチャネルが粒子内を酸性にして脱殻を助けることは各論で扱う（→K3）。

【2】覚えること
・HAが==シアル酸==に吸着 → ==エンドサイトーシス==で取り込まれる
・==エンドソーム内のpH低下== → HAの==構造変化== → ==融合ペプチドがエンドソーム膜に刺さる==
・==膜融合== → ==脱殻== → ゲノムRNAは細胞質へ出て==核へ運ばれる==
・融合の場所：HIV＝==形質膜（中性）==、インフルエンザ＝==エンドソーム膜（低pH）==

【3】試験ではこう出る
「インフルエンザウイルスの細胞内への侵入から脱殻までの過程に関係するのはどれか。2つ選べ」（==R7問10==）の正解は==膜融合・pH低下==。誤答は ==pH上昇==（向きの入れ替え）、==プロテアソーム==、==エクソサイトーシス==（放出の語）。同じ形の問いがアデノ版でR6問10・R5問10に出ており、そちらは膜融合が✕になる（次のブロック）。`,
