        heading: "ヘパドナウイルス——逆転写するDNAウイルスとcccDNA",
        body: `【1】しくみ
B型肝炎ウイルス（ヘパドナウイルス科、VII群）は、レトロとは逆向きに、DNAウイルスなのに複製の途中で逆転写を行う。粒子の中のゲノムは＋鎖の一部が欠けた不完全な環状二本鎖DNAである。核に入ると、ウイルスのP蛋白（DNAポリメラーゼ）が欠けた部分を埋めて、完全に閉じた環状二本鎖DNA＝cccDNA（covalently closed circular DNA）にする。cccDNAは宿主染色体に組み込まれないが、核内で安定して存在し続ける。宿主のRNAポリメラーゼがcccDNAから＋鎖RNAを作り、これがmRNAになると同時に、P蛋白の逆転写酵素活性（とRNaseH活性）によって二本鎖DNAに逆転写され、子ウイルスのゲノムになる。この逆転写の段階を止めるのが、B型慢性肝炎の治療に使う核酸アナログ（エンテカビルなど）で、作用機序は逆転写酵素阻害である。ただし核内のcccDNAには効かないので、薬をやめると再燃しうる（→K4）。

【2】覚えること
・ゲノムは==＋鎖の一部が欠けた不完全な環状二本鎖DNA==
・核内でP蛋白が完成させた==cccDNA==は==組み込まれず核内で安定に存在==
・==宿主のRNAポリメラーゼ==で＋鎖RNA → ==P蛋白の逆転写酵素活性==で二本鎖DNA
・P蛋白は==逆転写酵素活性とRNaseH活性==をもつ
・B型慢性肝炎の治療薬（核酸アナログ）は==逆転写酵素阻害==

【3】試験ではこう出る
「感染細胞内にcccDNAが出現するのはどれか」（==R7問41==）の正解は==B型肝炎ウイルス==。HIVは組み込まれる（プロウイルス）ので✕。「B型慢性肝炎の治療薬の作用機序はどれか」（==R6問71==）は==逆転写酵素阻害==で、「DNAウイルスだからDNAポリメラーゼ阻害」と短絡すると誤る。`,
