エンベロープのないウイルス（アデノ・ポリオ）は、細胞の中でビリオンの組み立てを完成させ、細胞を破壊して放出される。エンベロープをもつウイルスは、細胞の膜を出芽（budding）で取り込んでエンベロープにする。エンベロープの糖蛋白は小胞体（ER）からゴルジ体へ運ばれながら糖鎖の修飾を受けて合成され、どの膜にたまるかで出芽の場所が決まる。ヘルペスはヌクレオカプシドが核膜孔を出るときに核膜に出芽し、さらにゴルジ体に出芽して、エクソサイトーシスで細胞外に出る。B型肝炎ウイルスは小胞体、コロナはER-ゴルジ体に出芽し、どちらもエクソサイトーシスで出る。形質膜から出芽するのはマイナス鎖RNAウイルス（オルソミクソ・パラミクソ・ラブド・フィロ）とレトロで、出芽と放出が同時に起こるため、細胞の中で完成したビリオンはできない。形質膜から出芽し、しかもHAなどの赤血球凝集素をもつウイルスだけが、感染細胞の表面に赤血球を吸着させる（赤血球吸着。→G04）。

