日本の風疹ワクチンは、目的の置き方が変わってきた。1977〜1995年は中学生の女子だけに弱毒生ワクチンを1回打った。将来妊娠する女性本人をCRSから守る、個人免疫の発想である。1995年からは1歳以上の男女に、2006年からはMRワクチンを1歳と6歳の2回接種している。しかし女子だけに打った時代に中学生だった男性はワクチンを受けておらず、抗体保有率が低いまま大人になった。この世代の男性を中心に2013年と2018〜19年に風疹が流行し、CRSは2012年まで年数名だったのが2013年は32名に増えた。流行を抑えなければCRSは減らない、つまり妊婦を守るのは周囲の集団免疫だ、というのが講義の結論である。そこで2019年から40〜50代の男性（1962〜1979年生まれ）への追加接種が始まり、2021年以降CRSの届出はなく、2025年9月にWHOが日本の風疹排除を認定した。

