パラミクソ科とニューモ科のエンベロープには、レセプターに吸着する蛋白と、膜を融合させるF蛋白の2種類が並ぶ。吸着の蛋白は属で違い、レスピロ属・ルブラ属は血球凝集とノイラミニダーゼの両方の活性をもつHN蛋白、麻疹（モルビリ属）はノイラミニダーゼを欠くH蛋白、RSとヒトメタニューモはG蛋白で、G蛋白には血球凝集性がない。F蛋白は全員に共通で、F1とF2に開裂すると中性のままでエンベロープと形質膜を融合させ、ゲノムを細胞内へ直接送り込む。感染細胞の表面に出たF蛋白は隣の細胞の膜とも融合させるので、核をたくさん抱えた合胞体（多核巨細胞）ができる。RSウイルスの名（syncytial）はここから来ている。インフルエンザのHAは低pHのエンドソーム内でしか融合しないので、合胞体を作らない。

