麻疹ウイルスのH蛋白はノイラミニダーゼをもたず、レセプターもシアル酸ではない。最初のレセプターはリンパ球と樹状細胞がもつSLAM（CD150）で、気道に入ったウイルスはまず免疫細胞に感染してリンパ組織へ運ばれ、ウイルス血症で全身に広がる。免疫細胞そのものが傷むので、麻疹にかかると一過性に細胞性免疫が抑えられる。全身に運ばれたウイルスは、今度は上皮細胞のNectin4をレセプターにして気道や皮膚の上皮で増え、全身の発疹・呼吸器症状・肺炎を起こし、気道からウイルスを出す。H遺伝子の違いで遺伝子型はたくさんあるが、中和抗体はどの遺伝子型も中和できるので血清型は1つで、ワクチンは1価で足りる。複製は細胞質、出芽は形質膜からで、パラミクソ科の原則どおりである。SLAMに結合できないよう改変し、がん細胞に多いNectin4だけを狙わせた組換え麻疹ウイルスは、がん治療薬として治験が始まっている。

