        body: `【1】しくみ
HAが細胞表面の糖鎖末端のシアル酸に結合すると、ウイルスはエンドサイトーシスで取り込まれる。エンドソームの中が酸性になると、あらかじめHA1とHA2に開裂していたHAの形が変わり、HA2の融合ペプチドがエンドソーム膜に刺さって膜融合が起こる。同時にM2イオンチャネルが粒子の中に水素イオンを入れて vRNP をM1から外し、vRNP が細胞質に放たれる（脱殻）。vRNP は核に運ばれ、ポリメラーゼが転写を始める。このときウイルスは自分でキャップ構造を作れないので、宿主のmRNAの5′端のキャップをPB2でつかみ、PAで切り取ってプライマーにする（キャップスナッチング）。できたmRNAは細胞質で翻訳され、HA・NA・M2は形質膜へ運ばれ、新しい vRNP がそこに集まって出芽する。最後にNAがシアル酸を切り、細胞や仲間の粒子とつながったHAを外して粒子を放出する。パラミクソが中性の形質膜で融合したのとの違いが芯になる。

【2】覚えること
・吸着：==HA→糖鎖末端のシアル酸==
・侵入・脱殻：==エンドサイトーシス→エンドソーム内のpH低下でHAが膜融合==、==M2==が粒子内を酸性に
・転写：==核内でキャップスナッチング==（==PB2がキャップに結合、PAが切断==）
・放出：==形質膜から出芽→NAがシアル酸を切る==

【3】試験ではこう出る
R5問9・R4問5「細胞内に侵入する際の仕組み」の正解は==エンドソーム==（オートファジー・リソソーム・ゴルジ体・プロテアソームは誤答）。R7問10「侵入から脱殻に関係する（2つ）」は==膜融合・pH低下==で、「pH上昇」「エクソサイトーシス」が引っかけ。講義が予告した記述「A型インフルエンザの吸着〜放出」は5年分で未出題なので、上の4行を順に文章にして備える（→G03）。`,
