痘瘡（天然痘）はポックスウイルス科の二本鎖DNAウイルスによる全身感染症で、飛沫感染し、約12日の潜伏期のあと高熱と全身の発疹（紅斑→丘疹→水疱→膿疱→結痂）を起こし、致死率は20〜50%だった。ワクチン（種痘）は弱毒ウイルスの経皮接種で、ジェンナーが1798年に牛痘を使ったのが始まりだが、のちに使っていた株は牛痘でも痘瘡でもないワクシニアウイルスと分かった。WHOは接種率を上げるだけでなく、患者を探し出してその周りの感受性者に集中して打つ封じ込め方式をとり、1977年のソマリアの患者を最後に、1980年に根絶を宣言した。成功した理由は3つある。宿主がヒトだけで動物からの持ち込みが無いこと、症状で診断でき不顕性感染が無いので感染源を隔離できること、R0が5〜7と伝播効率が高くないこと、である。WHOが次に目標にした麻疹は前の2つを満たすがR0が16〜21と高く（→K3）、ポリオは不顕性感染が90%以上ある（→K2）。

