        heading: "移行免疫と新生児のIgM——胎盤を通るのはIgGだけ",
        body: `【1】しくみ
移行免疫は、胎盤を通して母親の抗体が胎児に移ることで、生後数か月の児が多くの感染症にかかりにくいのはこのためである。自分で作った抗体ではないので受動免疫の一つで、記憶されず数か月で消える。胎盤を通過できる抗体はIgGだけで、五量体で大きいIgMは通らず、細胞性免疫も移らない。移るのは母親が持っている抗体だけなので、母親が麻疹にかかったことがなくワクチンも受けていなければ、児は生後6か月未満でも麻疹にかかる。この「IgMは胎盤を通らない」を裏返すと、新生児の血中にあるIgMは母親由来ではありえず、胎児自身が作ったものだとわかる。生後すぐの新生児に風疹特異的IgMがあれば、胎内で風疹ウイルスに感染した証拠で、母親が妊娠中に感染したことも意味する（先天性風疹症候群の診断）。反対に新生児のIgGは母親からの移行抗体なので、感染の証拠にならない。

【2】覚えること
・移行免疫＝==胎盤を通るIgG==、==受動免疫==の一種
・移らないもの：==IgM==・==細胞性免疫==・==父親の免疫==
・移るのは==母親が持っている抗体だけ==（児によって違う）
・新生児の==IgM陽性＝胎内感染==、新生児の==IgG陽性＝母からの移行抗体==

【3】試験ではこう出る
移行免疫の正誤はR7問29・R6問31・R5問30の3年連続。R6・R5は選択肢まで同じで正解は「受動免疫の一種である」、R7は「IgG抗体である」が正解。✕は「IgM抗体である」「細胞性免疫も移行する」「父親の免疫も移行する」「すべての児で同じ免疫が移行する」「能動免疫の一種」「二次免疫応答が働く」。R7問38・R6問55「生後2日の新生児に風疹IgM」は「母親は妊娠中に感染」「新生児は胎児期に感染」の2つ（→G09・K2）。`,
