・回復の主役は==細胞性免疫==、感染細胞を壊すのは==CTL==
・==内因性抗原==（細胞内で作られる）→==CTL==＝細胞性免疫
・==外来性抗原==（粒子・壊れた蛋白）→==B細胞とTh2==＝液性免疫
・==生ワクチン＝内因性抗原==、==不活化ワクチン＝外来性抗原==（→G08）

【3】試験ではこう出る
