近縁な2種類のウイルスが1つの細胞に同時に感染すると、互いのゲノムが混ざる相互作用が起こる。分節のない1本のゲノムの中で配列がつなぎ替わるのが分子内遺伝子組み換えで、DNAウイルスとRNAウイルスで起こり方が違う。二本鎖DNAウイルス（ヘルペス科・アデノ科）では、相同な塩基配列を持つ領域でDNA鎖が切断・再結合される。アデノウイルスには多くの型があり、型の間の組み換えで新しい型が生まれる。一本鎖RNAウイルス（ピコルナ科のポリオ・コクサッキー・エコー・エンテロ）では、RNAポリメラーゼがゲノムを複製している途中で鋳型のRNAが別のウイルスのものに乗り換わる。ポリオ生ワクチンは1・2・3型のSabin株を混ぜた3価なので、経口接種すると同じ腸管の細胞に複数の型が感染し、便から型の混ざった組み換えウイルスが見つかる。組み換えで病原性の高いウイルスが生じ、ワクチン株由来ポリオの原因になりうる。

