        body: `【1】しくみ
エンベロープを持つウイルスは、宿主の膜と融合して中身を細胞に入れる。そのためにウイルス蛋白を宿主のプロテアーゼで開裂させる必要があるウイルスがあり、インフルエンザと新型コロナがその例である。プロテアーゼのある組織では、生まれた子ウイルスが開裂を受けて次の細胞に感染できる（多段増殖）が、無い組織では子ウイルスは感染性を持たず、1回で止まる。インフルエンザでは2段階で進む。Step 1：リガンドであるHA蛋白が、融合ペプチドの手前でプロテアーゼに切られてHA1とHA2になる（S-S結合でつながったまま）。Step 2：HAがシアル酸に吸着し、エンドサイトーシスで細胞内に取り込まれる。エンドソームの中のpHが下がるとHAの構造が変わり、HA2の端の融合ペプチドがエンドソーム膜に刺さって膜融合が進む。脱殻が起こってゲノムRNAが細胞質に出て、核へ運ばれる。Step 1が済んでいないHAは、pHが下がっても融合できない。

【2】覚えること
・開裂が必要なウイルス＝==インフルエンザ・新型コロナ==（エンベロープを持つ）
・プロテアーゼのある組織でだけ==多段増殖==できる
・HA→==HA1とHA2に開裂==（==S-S結合==でつながる）→==融合ペプチド==が露出
・侵入＝==エンドサイトーシス==→==エンドソーム内のpH低下==→構造変化→==膜融合==→脱殻

【3】試験ではこう出る
R5問9・R4問5（同じ問い）「インフルエンザが侵入に使う仕組み」の正解は==エンドソーム==（✕はオートファジー・リソソーム・ゴルジ体・プロテアソーム）。R7問10は「侵入から脱殻に関係するのを2つ」で正解は==膜融合とpH低下==、✕は「pH上昇」「エクソサイトーシス」（放出の語）。M2とアマンタジンは→K3。`,
