インフルエンザのレセプターであるシアル酸は全身の細胞にあるのに、季節性インフルエンザの感染は気道に限られる。レセプターだけでは説明できないこの問いに、前のブロックの開裂が答える。HAを開裂させる生体のプロテアーゼは、上気道から下気道全域の上皮細胞に発現しているセリンプロテアーゼのTMPRSS2とHATである。気道で生まれた子ウイルスだけが開裂したHAを持ち、次の細胞に感染できるので、病変は気道に限られる。この仕組みが見つかるきっかけは日本で研究されたセンダイウイルス（パラミクソウイルス科）だった。マウスのL細胞に感染させるときれいな細胞変化が起きるのに、増えたウイルスを新しい細胞にかけると感染しない。一方、発育鶏卵の漿尿膜腔では継代できる。培養細胞の剥離に使うトリプシンを低濃度で加えると、L細胞でも増えるようになった。卵の中には開裂酵素があり、L細胞には無かったのである。インフルエンザを培養細胞で増やすときに培養液にトリプシンを加えるのも同じ理由である。

【2】覚えること
