・感染価の測定＝==プラック法・終末価法==。最も精度が高いのは==プラック法==
・感染できない粒子＝==不完全粒子==（臨床検体には少なからず含まれる）
・電子顕微鏡は==ラテックス粒子との比==で濃度を出す（欠点＝==精製した大量のウイルスが必要==）

【3】試験ではこう出る
