        heading: "PFU/mLの計算——プラック数÷接種量×希釈倍数",
        body: `【1】しくみ
プラックの数と感染性粒子の数は比例するので、プラックを数えれば元の液の感染価が出る。ただし原液のままでは細胞が全部死んで数えられないので、実際にはウイルス液を10倍ずつ階段希釈して接種し、数えやすい数（数十個）のプラックができた希釈の皿を使う。計算は2段階で、まず接種量で割って「希釈した液1mLあたり」に直し、次に希釈倍数を掛けて「原液1mLあたり」に戻す。講義の例（10倍階段希釈した液を0.1mLずつ接種）では、10⁻⁵の皿は多すぎて数えられず、10⁻⁶の皿に17個、10⁻⁷の皿に2個のプラックができた。17個の皿を使うと 17÷0.1×10⁶＝1.7×10⁸ PFU/mL になる。

【2】覚えること
・PFU/mL＝==プラック数÷接種量（mL）×希釈倍数==
・接種量が==0.1mLなら×10、0.2mLなら×5==
・数えるのは==数十個のプラックができた希釈==の皿

【3】試験ではこう出る
R6問25「1万倍希釈した液0.2mLで24個のプラック」の正解は==1.2×10⁶ PFU/mL==（24÷0.2＝120、×10⁴）。誤答は接種量で割り忘れた==2.4×10⁵==、割らずに掛けた==4.8×10⁴==、桁をずらした==2.4×10⁶==など。接種量と希釈倍数を変えれば何度でも出し直せる問いなので、「割る→掛ける」の順に計算する癖をつける。`,
        slides: [9],
